    # Locate full separator rows and columns.
    sep_rows = [r for r in range(h) if all(v == grid[r][0] and v != 0 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[0][c] == grid[r][c] and grid[0][c] != 0 for r in range(h))]
