    row_starts = [0] + [r + 1 for r in sep_rows]
    row_ends = sep_rows + [h]
    col_starts = [0] + [c + 1 for c in sep_cols]
    col_ends = sep_cols + [w]

    # Find the patterned cell, which is a nonempty cell outside the first column.
    template = None
    for ri, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        for ci, (c0, c1) in enumerate(zip(col_starts, col_ends)):
            if ci == 0:
