    # Keep the separators.
    for r in sep_rows:
        for c in range(w):
            out[r][c] = sep_color
    for c in sep_cols:
        for r in range(h):
            out[r][c] = sep_color

    # The color marker in the first cell of each band colors that band’s pattern.
    for ri, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        marker = next((grid[r][c] for r in range(r0, r1)
                       for c in range(col_starts[0], col_ends[0])
                       if grid[r][c] not in (0, sep_color)), 0)
